package com.campusnova.service; import com.campusnova.model.ChatHistory; import com.campusnova.repository.ChatHistoryRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ConversationService { private final ChatHistoryRepository history; public ConversationService(ChatHistoryRepository h){history=h;} public List<String> recentTerms(String session){if(session==null||session.trim().isEmpty())return Collections.emptyList();List<String> terms=new ArrayList<String>();for(ChatHistory item:history.findTop20BySessionIdOrderByCreatedAtDesc(session)){terms.add(item.getQuestion());if(terms.size()==3)break;}return terms;} }
